public void for_RewriteFnApp(_RewriteFnApp x) {
    debug("for_RewriteFnApp ", x,
                 " args = ", x.getArgument(), " function = ", x.getFunction(),
          " function class = ", x.getFunction());
    if (x == emittingNumeralSite) {
        emitNumeralCoercionCall(x);
        return;
    }
    String siteDesc = numeralCoercionSiteDesc(x);
    if (siteDesc != null) {
        if (emitFoldedNumeral(x, siteDesc)) return;
        numeralSite(x, x, siteDesc);
        return;
    }
    if (isNumeralCoercionCall(x)) {
        // A place whose value depends on a type variable: the call runs at each evaluation.
        emitNumeralCoercionCall(x);
        return;
    }
    emitFnApp(x);
}

private void emitFnApp(_RewriteFnApp x) {
    // This is a little weird.  If a function takes no arguments the parser gives me a void literal expr
    // however I don't want to be putting a void literal on the stack because it gets in the way.
    int savedParamCount = paramCount;
    boolean savedFnRefIsApply = fnRefIsApply;
    try {
        Expr arg = x.getArgument();
        Expr fn = x.getFunction();

        // need to use closure if fn is generic and instantiating with a
        // tuple type for the entire parameter list.
        boolean useClosure =
            !(fn instanceof FunctionalRef) 
            || ((FunctionalRef) fn).getStaticArgs().size() > 0
            || (fn instanceof FnRef && localFunctionOrNull((FnRef) fn) != null)
            ;

        if (useClosure) {
            if (fn instanceof FunctionalRef && ((FunctionalRef) fn).getStaticArgs().size() > 0 &&
                assumptionCount(callArgList(arg)) > 0)
                refuseGenericAssumption((FunctionalRef) fn);
            // Higher-order call.
            fn.accept(this); // Puts the VarRef function on the stack.
        }
        fnRefIsApply = false;
        Type domain_type = ((ArrowType)(x.getFunction().getInfo().getExprType().unwrap())).getDomain();
        evalArg(x, domain_type, arg);
        fnRefIsApply = true;
        if (useClosure) {
            generateHigherOrderCall(exprType(fn));
        } else {
            callArgsForAssumption = callArgList(arg);
            try {
                x.getFunction().accept(this);
            } finally {
                callArgsForAssumption = null;
            }
        }
    } finally {
        paramCount = savedParamCount;
        fnRefIsApply = savedFnRefIsApply;
    }
}

public void for_RewriteFnOverloadDecl(_RewriteFnOverloadDecl x) {
    /* Note for refactoring -- this code does it the "right" way.
     * And also, this code NEEDS refactoring.
     */
    List<IdOrOp> fns = x.getFns();
    IdOrOp name = x.getName();
    com.sun.fortress.nodes.Type ty = x.getType().unwrap();
    Relation<IdOrOpOrAnonymousName, Function> fnrl = ci.functions();

    MultiMap<Integer, OverloadSet.TaggedFunctionName> byCount =
        new MultiMap<Integer,OverloadSet.TaggedFunctionName>();

    // System.err.println(NodeUtil.getSpan(x) + ": _RewriteFnOverloadDecl " + name +
    //                    "\n  candidates " + fns);

    for (IdOrOp fn : fns) {

        Option<APIName> fnapi = fn.getApiName();
        PredicateSet<Function> set_of_f;
        APIName apiname;

        if (fnapi.isNone()) {
            apiname = thisApi();
            set_of_f = fnrl.matchFirst(fn);
        } else {

            IdOrOp fnnoapi = NodeFactory.makeLocalIdOrOp(fn);
            apiname = fnapi.unwrap();
            ApiIndex ai = env.api(apiname);
            set_of_f = ai.functions().matchFirst(fnnoapi);
        }

        for (Function f : set_of_f) {
            /* This guard should be unnecessary when proper overload
               disambiguation is working.  Right now, the types are
               "too accurate" which causes a call to an otherwise
               non-existent static method.
            */
            if (true // || OverloadSet.functionInstanceofType(f, ty, ta)
                    ) {
                OverloadSet.TaggedFunctionName tagged_f =
                    new OverloadSet.TaggedFunctionName(apiname, f);
                byCount.putItem(f.parameters().size(), tagged_f);
            }
        }
    }

    /* The name lists the declarations, so two such nodes of one name, made for calls at
       two arrows, write the same set: the first writes it. */
    String nm = name.stringName();
    boolean setWritten = !rewrittenOverloadsWritten.add(nm);

    for (Map.Entry<Integer, Set<OverloadSet.TaggedFunctionName>> entry :
             byCount.entrySet()) {
        int i = entry.getKey();
        Set<OverloadSet.TaggedFunctionName> fs = entry.getValue();
        if (fs.size() > 1) {
            OverloadSet os = new OverloadSet.AmongApis(thisApi(), name,
                                                       typeAnalyzer, fs, i);

            /* The split finds the set's principal member, the declaration than which
               each other is more specific, at whose signature the set's method is
               written; without it the set writes no method. */
            os.split(true);
            if (!setWritten) {
                os.generateAnOverloadDefinition(nm, cw);
                rewrittenOverloadsWritten.addAll(os.getOverloadSubsets().keySet());
            }
            if (ty instanceof ArrowType)
                forwardToPrincipal(nm, (ArrowType) ty, os);
        }
    }

}

/* The names of the overload methods that for_RewriteFnOverloadDecl has written, each
   also with its signature. */
private final Set<String> rewrittenOverloadsWritten = new HashSet<String>();

/*
 * The overload method nm at the signature of the call's arrow ty, where that is not the
 * principal member's: it passes its arguments to the method at the principal member's
 * signature.  The call names the method at the arrow of the declaration that the checker
 * chose, and where a trait's functional method and that of an object that the trait's
 * comprises clause lists tie, the checker chooses either, so the call can name it at the
 * object's narrower parameter types.  No method is written where the set has no principal
 * member, or a generic one, or where the two signatures differ in their number of
 * parameters.
 */
private void forwardToPrincipal(String nm, ArrowType ty, OverloadSet os) {
    String principalSig = os.getSignature();
    if (!os.getOverloadSubsets().containsKey(nm + principalSig)) return;
    String callSig = NamingCzar.jvmMethodDesc(ty, component.getName());
    if (callSig.equals(principalSig) || rewrittenOverloadsWritten.contains(nm + callSig)) return;
    /* Each argument is a reference, as every Fortress value is. */
    List<String> callArgs = NamingCzar.parseArgs(Naming.mangleMethodSignature(callSig));
    if (callArgs.size() != NamingCzar.parseArgs(Naming.mangleMethodSignature(principalSig)).size())
        return;
    for (String a : callArgs)
        if (a.charAt(0) != 'L') return;
    rewrittenOverloadsWritten.add(nm + callSig);
    MethodVisitor fmv = cw.visitMethod(ACC_PUBLIC + ACC_STATIC, nm, callSig, null, null);
    fmv.visitCode();
    for (int k = 0; k < callArgs.size(); k++)
        fmv.visitVarInsn(ALOAD, k);
    fmv.visitMethodInsn(INVOKESTATIC, packageAndClassName, nm, principalSig);
    if (!callSig.substring(callSig.indexOf(')')).equals(principalSig.substring(principalSig.indexOf(')'))))
        InstantiatingClassloader.generalizedCastTo(fmv, NamingCzar.jvmTypeDesc(ty.getRange(), thisApi(), false, true));
    fmv.visitInsn(ARETURN);
    fmv.visitMaxs(Naming.ignoredMaxsParameter, Naming.ignoredMaxsParameter);
    fmv.visitEnd();
}

